/**
 * npm run codegen -w video [-- --check]
 *
 * src/generated/spec.schema.json (exported from the agent's Pydantic models) ->
 *   src/generated/spec.ts      TypeScript types (json-schema-to-typescript)
 *   src/generated/spec.zod.ts  zod validators (json-schema-to-zod)
 * --check exits 1 when the generated files differ from what would be generated (CI).
 */
import fs from 'node:fs';
import path from 'node:path';
import { compile, type JSONSchema } from 'json-schema-to-typescript';
import { jsonSchemaToZod } from 'json-schema-to-zod';
import { format, resolveConfig } from 'prettier';
import { VIDEO_ROOT } from './lib/bundle';

const GEN = path.join(VIDEO_ROOT, 'src', 'generated');
const HEADER = '/* GENERATED by `npm run codegen -w video` from spec.schema.json - do not edit. */\n';

const pretty = async (code: string, file: string) =>
  format(code, { ...(await resolveConfig(file)), filepath: file });

export const generate = async (): Promise<Record<string, string>> => {
  const schema = JSON.parse(fs.readFileSync(path.join(GEN, 'spec.schema.json'), 'utf8')) as JSONSchema & {
    $defs?: Record<string, unknown>;
  };

  const types = await compile(schema, 'VideoSpec', {
    bannerComment: '',
    additionalProperties: false,
    unreachableDefinitions: true,
    ignoreMinAndMaxItems: true,
    format: false,
    style: { singleQuote: true },
  });

  // One named zod export per definition, emitted in dependency order. `$ref` becomes a reference
  // to the named schema and a Pydantic discriminated union becomes z.discriminatedUnion.
  const defs = (schema.$defs ?? {}) as Record<string, Record<string, unknown>>;
  const refName = (ref: string) => ref.split('/').pop() ?? ref;
  const parserOverride = (s: Record<string, unknown>): string | void => {
    if (typeof s.$ref === 'string') return `${refName(s.$ref)}Schema`;
    const disc = s.discriminator as { propertyName?: string } | undefined;
    if (disc?.propertyName && Array.isArray(s.oneOf)) {
      const members = (s.oneOf as { $ref: string }[]).map((m) => `${refName(m.$ref)}Schema`);
      return `z.discriminatedUnion('${disc.propertyName}', [${members.join(', ')}])`;
    }
  };
  const deps = (node: unknown, out = new Set<string>()): Set<string> => {
    if (Array.isArray(node)) node.forEach((n) => deps(n, out));
    else if (node && typeof node === 'object') {
      for (const [k, v] of Object.entries(node)) {
        if (k === '$ref' && typeof v === 'string') out.add(refName(v));
        else deps(v, out);
      }
    }
    return out;
  };
  const order: string[] = [];
  const visit = (name: string) => {
    if (order.includes(name)) return;
    for (const d of deps(defs[name])) visit(d);
    order.push(name);
  };
  Object.keys(defs).sort().forEach(visit);

  const toZod = (s: unknown) =>
    jsonSchemaToZod(s as never, { module: 'none', zodVersion: 4, parserOverride: parserOverride as never });
  const parts: string[] = ["import { z } from 'zod';", ''];
  for (const name of order) parts.push(`export const ${name}Schema = ${toZod(defs[name])};`);
  const { $defs: _defs, ...root } = schema as Record<string, unknown>;
  parts.push(`export const VideoSpecSchema = ${toZod(root)};`);

  const files: Record<string, string> = {
    'spec.ts': await pretty(HEADER + types, path.join(GEN, 'spec.ts')),
    'spec.zod.ts': await pretty(HEADER + parts.join('\n'), path.join(GEN, 'spec.zod.ts')),
  };
  return files;
};

const main = async () => {
  const check = process.argv.includes('--check');
  const files = await generate();
  let stale = false;
  for (const [name, code] of Object.entries(files)) {
    const file = path.join(GEN, name);
    const current = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : '';
    if (check) {
      if (current !== code) {
        console.error(`✗ stale: src/generated/${name} (run npm run codegen -w video)`);
        stale = true;
      }
    } else {
      fs.writeFileSync(file, code);
      console.log(`✓ src/generated/${name}`);
    }
  }
  if (stale) process.exit(1);
  if (check) console.log('✓ generated files are up to date');
};

if (process.argv[1] && path.resolve(process.argv[1]).endsWith('codegen.ts')) await main();
